#!/bin/bash
# Darker, scarier red/black grade: crushed shadows, drifting smoke (luma only), grain, flicker, heavy vignette. Keeps reds, flags and white captions.
ffmpeg -v error -y -i "$1" -loop 1 -i "$(dirname "$0")/assets/smoke.png" -filter_complex "[0:v]format=rgb24,curves=all='0/0 0.22/0.1 0.5/0.34 0.8/0.7 1/0.98',eq=saturation=0.9,format=yuv444p[v];[1:v]crop=1080:1920:'100+60*sin(t/3)':'100+mod(t*14\,400)',format=yuv444p,lutyuv=y='val*0.55':u=128:v=128[sm];[v][sm]blend=c0_mode=screen:c0_opacity=0.35:c1_mode=normal:c1_opacity=1:c2_mode=normal:c2_opacity=1:shortest=1,unsharp=5:5:0.6,format=yuv420p,noise=c0s=14:c0f=t+u,eq=brightness='0.015*sin(t*29)*sin(t*7)':eval=frame,vignette=angle=PI/3.2,format=yuv420p[o]" -map "[o]" -map 0:a -c:v libx264 -crf 29 -preset veryfast -maxrate 9M -bufsize 18M -c:a copy -movflags +faststart -shortest "$2"
